package com.neml.badminton.dto;
import com.neml.badminton.entity.ConfigurationStatus; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*;
public class SportConfigurationDtos {
 public record RubberRuleDto(String rubberCode,String displayLabel,String shortLabel,int displayOrder,int participantCountPerSide,String genderRule,int bestOfGames,int pointsPerGame,int winBy,int scoreCap,boolean enabled){}
 public record BadmintonConfigDto(int version,ConfigurationStatus status,String presetCode,int maximumAppearancesPerPlayer,boolean multipleRubberCategoriesAllowed,boolean lineupChangesAfterStartAllowed,String tieHandling,String walkoverPolicy,String retirementPolicy,String lineupVisibilityPolicy,List<RubberRuleDto> rubbers){}
 public record BadmintonConfigRequest(@NotNull Integer expectedVersion,@NotBlank String presetCode,@Min(1)int maximumAppearancesPerPlayer,boolean multipleRubberCategoriesAllowed,boolean lineupChangesAfterStartAllowed,@Pattern(regexp="LEAGUE_TIE|ADMINISTRATIVE_WIN")String tieHandling,@NotBlank String walkoverPolicy,@NotBlank String retirementPolicy,@NotBlank String lineupVisibilityPolicy,@NotEmpty List<@Valid RubberRuleRequest> rubbers){}
 public record RubberRuleRequest(@NotBlank String rubberCode,@NotBlank String displayLabel,@NotBlank String shortLabel,@Min(1)int displayOrder,@Min(1)@Max(2)int participantCountPerSide,@Pattern(regexp="MALE|FEMALE|MIXED|OPEN")String genderRule,@Min(1)int bestOfGames,@Min(1)int pointsPerGame,@Min(1)int winBy,@Min(1)int scoreCap,boolean enabled){}
 public record CricketConfigDto(int version,ConfigurationStatus status,String presetCode,int playersPerSide,int oversPerInnings,int maximumOversPerBowler,int requiredWicketkeepers,String tiePolicy,int maximumSuperOvers,String powerplayRanges,int wideBallRuns,int noBallRuns,boolean freeHitEnabled,boolean tossRequired,String abandonmentPolicy,boolean administrativeTargetOverrideAllowed,boolean administrativeResultOverrideAllowed,String playingXiLockPolicy,String netRunRatePolicy){}
 public record CricketConfigRequest(@NotNull Integer expectedVersion,@Pattern(regexp="T10|T20|ODI|CUSTOM")String presetCode,@Min(2)@Max(11)int playersPerSide,@Min(1)@Max(50)int oversPerInnings,@Min(1)int maximumOversPerBowler,@Min(1)int requiredWicketkeepers,@Pattern(regexp="SUPER_OVER|TIE|ADMINISTRATIVE")String tiePolicy,@Min(0)int maximumSuperOvers,@NotBlank String powerplayRanges,@Min(1)int wideBallRuns,@Min(1)int noBallRuns,boolean freeHitEnabled,boolean tossRequired,@Pattern(regexp="ADMINISTRATIVE_NO_RESULT|ADMINISTRATIVE_RESULT")String abandonmentPolicy,boolean administrativeTargetOverrideAllowed,boolean administrativeResultOverrideAllowed,@Pattern(regexp="LOCK_ON_SUBMISSION")String playingXiLockPolicy,@Pattern(regexp="STANDARD")String netRunRatePolicy){}
 public record QuotaRuleDto(String ruleCode,String categoryType,String categoryValue,Integer minimumCount,Integer maximumCount,String appliesTo,boolean enabled,String validationMessage){}
 public record QuotaRuleRequest(@NotBlank String ruleCode,@Pattern(regexp="GENDER|SKILL_LEVEL|PLAYER_CATEGORY")String categoryType,@NotBlank String categoryValue,@Min(0)Integer minimumCount,@Min(0)Integer maximumCount,@Pattern(regexp="SQUAD|PLAYING_SIDE")String appliesTo,boolean enabled,@Size(max=255)String validationMessage){}
}
